// Thrown-range text for hand grenades. Pass the wielder's STR modifier for a
// live distance; pass null (portal / static surfaces) to print the formula.
function reqProfilesText(it) {   // one compact line per fire profile, for row notes & catalog cards
  if (!it || !it.profiles) return '';
  return it.profiles.map(function(p) {
    return p.name + ': ' + (p.dmg || '—')
      + (p.range ? ' (' + p.range + ')' : '')
      + (p.save ? ' — DC ' + p.save.dc + ' ' + p.save.ability + ' save' : '')
      + (p.effect ? ' — ' + p.effect : '');
  }).join(' · ') + (it.profile_switch ? ' · Switch: ' + it.profile_switch : '');
}

function reqThrownText(it, strMod) {
  if (!it.thrown) return it.range;
  var t = it.thrown;
  if (strMod === null || strMod === undefined) {
    return 'Thrown ' + t.base + '+' + t.perStr + '×STR ft · ' + it.range;
  }
  return 'Thrown ' + (t.base + t.perStr * strMod) + ' ft · ' + it.range;
}
